#!/usr/bin/env python3
"""Serialize manually authored source judgements. No keyword/headline-based verdicts."""
from pathlib import Path
from datetime import datetime,timezone
import json,csv,re
ROOT=Path('/workspace/scratch/26604d0a9a98');W=ROOT/'work/cotes6_7'
PKG='MPL_6_038-067+7_001-060';DATE='2026-11-19'
items=[];claims=[];problems=[];entries=[];events=[];readings=[];links=[]
WHO='GPT-6 Astra Pro; effort not exposed; run SA15-20261119/cotes6_7'
TEX='SA15_texts/pro/'+PKG+'_transcription.tex'

def I(n,sources,cote,scans,lines,kind,words,statement,reconstruction,check,reason,corrections=None):
    iid=f'P67-I{n:03}'
    ss=[f'{PKG}##{j}' for j in sources]
    items.append(dict(id=iid,sources=ss,kind=kind,cote=cote,scans=scans,lines={'file':TEX,'ranges':lines,'convention':'1-based transcription-file lines, not manuscript lineation'},his_words=words,statement=statement,reconstruction=reconstruction,check=check,check_reason=reason))
    corrections=corrections or {}
    for k,j in enumerate(sources):
        v,r=corrections.get(j,('kept' if k==0 else 'merged',reason))
        entries.append(dict(entry_id=f'{PKG}##{j}',item_id=iid,verdict=v,reason=r))
    events.append(dict(statement_id=iid,date=DATE,who=WHO,type='used and rechecked in this run',outcome='Note(s) compared with the complete specified transcription passage; '+check+': '+reason))
    return iid

def C(n,ii,cote,scans,lines,his,statement,status,computation,cls,fate,date,present,refs,confidence='medium',search=None):
    cid=f'P67-C{n:03}'
    claims.append(dict(id=cid,items=[f'P67-I{i:03}' for i in ii],cote=cote,scans=scans,lines={'file':TEX,'ranges':lines},his_statement=his,statement=statement,status_on_pages=status,computation=computation,**{'class':cls},fate=fate,fate_date=date,present_status={'as_of':'2026-11-19','status':present},refs=refs,confidence=confidence,search_history=search or []))
    events.append(dict(statement_id=cid,date=DATE,who=WHO,type='carried as background without fault found',outcome='Recorded manuscript status and searched literature fate; no blanket certification of the proof is implied. '+present))
    return cid

def P(n,title,occ,ashe,today,art,why,worth,refs):
    problems.append(dict(id=f'P67-P{n:03}',title=title,occurrences=occ,as_he_states=ashe,plausible_today=today,state_of_art=art,why_open=why,worth=worth,refs=refs))

def R(cote,scan,line,reading,alternative,evidence,weight='high',confidence='medium'):
    readings.append(dict(cote=cote,scan=scan,line=f'{TEX}:{line}',reading=reading,alternative=alternative,evidence=evidence,weight=weight,confidence=confidence))

def L(kind,frm,to,what,evidence,notes):
    links.append({'kind':kind,'from':frm,'to':to,'what':what,'evidence':evidence,'note_ids':';'.join(f'{PKG}##{j}' for j in notes)})

def dump():
    for name,data in [('items',items),('claims',claims),('problems',problems)]:
        (W/f'{name}.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
    for name,data,fields in [('supplementary_entries',entries,['entry_id','item_id','verdict','reason']),('check_events',events,['statement_id','date','who','type','outcome']),('readings',readings,['cote','scan','line','reading','alternative','evidence','weight','confidence']),('links',links,['kind','from','to','what','evidence','note_ids'])]:
        with (W/f'{name}.tsv').open('w') as f:
            ww=csv.DictWriter(f,fieldnames=fields,delimiter='\t');ww.writeheader();ww.writerows(data)
    summary={'items':len(items),'claims':len(claims),'problems':len(problems),'supplementary_entries':len(entries),'readings':len(readings),'links':len(links)}
    (W/'outputs/build_records_output.json').write_text(json.dumps(summary,indent=2)+'\n')
    print(json.dumps(summary))

